// Log workflow start
const workflowStartTime = new Date();

return [{
  json: {
    workflow_name: 'fda_510k_scraper',
    execution_id: $execution.id,
    start_time: workflowStartTime.toISOString(),
    status: 'started'
  }
}];

// Prepare FDA 510k search parameters
const scraperState = $input.first().json;
const lastItemDate = scraperState.last_item_date || '2024-01-01';

// FDA 510k database search URL
const baseUrl = 'https://www.accessdata.fda.gov/scripts/cdrh/cfdocs/cfpmn/pmn.cfm';

// Build search parameters for recent submissions
const searchParams = {
  start: lastItemDate,
  pagenum: 1,
  sortcolumn: 'decisiondate',
  sortorder: 'DESC'
};

return [{
  json: {
    url: baseUrl,
    params: searchParams,
    method: 'GET',
    last_check_date: lastItemDate
  }
}];

// Parse FDA 510k HTML response
const htmlContent = $input.first().json.body || $input.first().json;
const items = [];

try {
  // In production, use Puppeteer or Cheerio for proper HTML parsing
  // This is a simplified example - actual implementation needs HTML parser

  // Simulated parsing logic (replace with actual HTML parsing)
  // Extract table rows from FDA 510k results page

  const regex = /<tr[^>]*>(.*?)<\/tr>/gis;
  const matches = htmlContent.match(regex) || [];

  // Skip header row
  for (let i = 1; i < Math.min(matches.length, 100); i++) {
    const row = matches[i];

    // Extract cells (simplified - use proper HTML parser)
    const cellRegex = /<td[^>]*>(.*?)<\/td>/gis;
    const cells = [...row.matchAll(cellRegex)].map(m => m[1].replace(/<[^>]*>/g, '').trim());

    if (cells.length >= 5) {
      items.push({
        fda_number: cells[0],
        applicant_name: cells[1],
        device_name: cells[2],
        approval_date: cells[3],
        decision: cells[4],
        product_code: cells[5] || '',
        scraped_at: new Date().toISOString()
      });
    }
  }

  console.log(`Parsed ${items.length} FDA 510k records`);

  return items.map(item => ({ json: item }));

} catch (error) {
  console.error('Error parsing FDA data:', error.message);
  return [{
    json: {
      error: true,
      message: error.message,
      items_parsed: 0
    }
  }];
}

// Use OpenAI to extract company names and match to database
const items = $input.all();
const enrichedItems = [];

for (const item of items) {
  const data = item.json;

  // Skip error items
  if (data.error) continue;

  // Extract company name variations
  let companyName = data.applicant_name;

  // Clean up company name (remove Inc, LLC, Corp, etc.)
  companyName = companyName
    .replace(/\s+(Inc\.?|LLC|Corp\.?|Corporation|Ltd\.?|Limited|Co\.?)$/i, '')
    .trim();

  enrichedItems.push({
    ...data,
    company_name_cleaned: companyName,
    approval_type: '510k'
  });
}

return enrichedItems.map(item => ({ json: item }));

// Merge FDA data with company IDs
const fdaData = $input.all();
const results = [];

for (const item of fdaData) {
  const data = item.json;

  // Check if company was found
  const companyId = data.id || null;

  results.push({
    company_id: companyId,
    approval_type: '510k',
    device_name: data.device_name,
    device_classification: data.product_code,
    product_code: data.product_code,
    approval_date: data.approval_date,
    fda_number: data.fda_number,
    applicant_name: data.applicant_name,
    decision: data.decision,
    source_url: `https://www.accessdata.fda.gov/scripts/cdrh/cfdocs/cfpmn/pmn.cfm?ID=${data.fda_number}`,
    raw_data: JSON.stringify(data),
    created_at: new Date().toISOString()
  });
}

return results.map(r => ({ json: r }));

// Identify high-priority approvals for alerts
const approvals = $input.all();
const alerts = [];

for (const approval of approvals) {
  const data = approval.json;

  // Check if this is a high-priority approval
  const isHighPriority = 
    data.decision === 'Substantially Equivalent (SESE)' ||
    data.device_name.toLowerCase().includes('cardiovascular') ||
    data.device_name.toLowerCase().includes('surgical') ||
    data.device_name.toLowerCase().includes('implant');

  if (isHighPriority && data.company_id) {
    alerts.push({
      company_id: data.company_id,
      alert_type: 'fda_approval',
      priority: 'high',
      title: `New 510(k) Approval: ${data.device_name}`,
      description: `${data.applicant_name} received 510(k) clearance for ${data.device_name} on ${data.approval_date}`,
      data: JSON.stringify(data),
      action_url: data.source_url,
      created_at: new Date().toISOString()
    });
  }
}

console.log(`Generated ${alerts.length} high-priority alerts`);

if (alerts.length > 0) {
  return alerts.map(a => ({ json: a }));
} else {
  // Return empty result to skip alert creation
  return [];
}

// Format Slack alert message
const alerts = $input.all();
const messages = [];

for (const alert of alerts) {
  const data = alert.json;

  const message = {
    text: `🚨 *${data.title}*`,
    blocks: [
      {
        type: 'header',
        text: {
          type: 'plain_text',
          text: data.title
        }
      },
      {
        type: 'section',
        text: {
          type: 'mrkdwn',
          text: data.description
        }
      },
      {
        type: 'section',
        fields: [
          {
            type: 'mrkdwn',
            text: `*Priority:*\n${data.priority.toUpperCase()}`
          },
          {
            type: 'mrkdwn',
            text: `*Type:*\nFDA 510(k) Approval`
          }
        ]
      },
      {
        type: 'actions',
        elements: [
          {
            type: 'button',
            text: {
              type: 'plain_text',
              text: 'View FDA Record'
            },
            url: data.action_url,
            style: 'primary'
          }
        ]
      }
    ]
  };

  messages.push(message);
}

return messages.map(m => ({ json: m }));

// Calculate workflow statistics
const startTime = $node['Initialize Workflow'].json.start_time;
const endTime = new Date();
const duration = (endTime - new Date(startTime)) / 1000;

const recordsProcessed = $input.all().length || 0;

return [{
  json: {
    workflow_name: 'fda_510k_scraper',
    execution_id: $execution.id,
    status: 'success',
    start_time: startTime,
    end_time: endTime.toISOString(),
    duration_seconds: Math.round(duration),
    records_processed: recordsProcessed,
    records_inserted: recordsProcessed,
    records_updated: 0,
    records_failed: 0,
    errors: [],
    metadata: {
      alerts_created: $node['Identify High-Priority Approvals']?.json?.length || 0
    }
  }
}];
